<?php require_once '../includes/bootstrap.php'; require_role('admin');$pdo=db();$id=(int)($_GET['id']??0);$course=['title'=>'','short_description'=>'','description'=>'','topics'=>'','level'=>'Beginners','image'=>'course-web-development.jpg','is_active'=>1];$errors=[];if($id){$s=$pdo->prepare('SELECT * FROM courses WHERE id=?');$s->execute([$id]);$course=$s->fetch()?:$course;}if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf())$errors[]='Security check failed.';foreach(['title','short_description','description','topics','level','image'] as $k)$course[$k]=trim($_POST[$k]??'');$course['is_active']=isset($_POST['is_active'])?1:0;if(strlen($course['title'])<3)$errors[]='Title is required.';if(strlen($course['short_description'])<10)$errors[]='Short description is required.';if(strlen($course['description'])<20)$errors[]='Description is required.';if(strlen($course['topics'])<2)$errors[]='Topics are required.';if(strlen($course['image'])<3||!preg_match('/^[a-zA-Z0-9._-]+$/',$course['image']))$errors[]='Image filename is invalid.';if(!$errors){if($id){$s=$pdo->prepare('UPDATE courses SET title=?,short_description=?,description=?,topics=?,level=?,image=?,is_active=? WHERE id=?');$s->execute([$course['title'],$course['short_description'],$course['description'],$course['topics'],$course['level'],$course['image'],$course['is_active'],$id]);flash('success','Course updated.');}else{$s=$pdo->prepare('INSERT INTO courses(title,short_description,description,topics,level,image,is_active) VALUES(?,?,?,?,?,?,?)');$s->execute([$course['title'],$course['short_description'],$course['description'],$course['topics'],$course['level'],$course['image'],$course['is_active']]);flash('success','Course created.');}redirect('admin/index.php');}}page_head($id?'Edit Course':'Add Course');site_header(); ?>
<main><section class="narrow"><div class="form-card"><p class="section-label">COURSE CRUD</p><h1><?= $id?'Edit':'Add' ?> course</h1><?php if($errors): ?><div class="alert error" role="alert"><ul><?php foreach($errors as $x): ?><li><?= e($x) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-group"><label for="title">Title</label><input id="title" name="title" required value="<?= e($course['title']) ?>"></div><div class="form-group"><label for="short_description">Short description</label><textarea id="short_description" name="short_description" required rows="3"><?= e($course['short_description']) ?></textarea></div><div class="form-group"><label for="description">Full description</label><textarea id="description" name="description" required rows="6"><?= e($course['description']) ?></textarea></div><div class="form-group"><label for="topics">Topics</label><input id="topics" name="topics" required value="<?= e($course['topics']) ?>"></div><div class="form-group"><label for="level">Level</label><select id="level" name="level"><option <?= $course['level']==='Beginners'?'selected':'' ?>>Beginners</option><option <?= $course['level']==='Intermediate'?'selected':'' ?>>Intermediate</option><option <?= $course['level']==='Students'?'selected':'' ?>>Students</option></select></div><div class="form-group"><label for="image">Image filename</label><input id="image" name="image" required value="<?= e($course['image']) ?>"><small>Use a filename already present in the images folder.</small></div><label class="checkbox"><input type="checkbox" name="is_active" <?= $course['is_active']?'checked':'' ?>> Active course</label><div class="hero-buttons"><button class="button primary-button" type="submit">Save course</button><a class="button secondary-button" href="<?= e(url('admin/index.php')) ?>">Cancel</a></div></form></div></section></main><?php site_footer(); ?>